#!/usr/bin/env python3
# Generated by https://github.com/kyuridenamida/atcoder-tools
import sys
import heapq

INF = float('inf')


def solve(N: int, M: int, S: int, U: "List[int]", V: "List[int]", A: "List[int]", B: "List[int]", C: "List[int]", D: "List[int]"):
    MAX = max(A) * (N-1)
    S = min(S, MAX)

    G = [[] for _ in range(N)]
    for u, v, a, b in zip(U, V, A, B):
        G[u-1].append([v-1, [a, b]])
        G[v-1].append([u-1, [a, b]])

    dp = [[INF for _ in range(MAX + 1)] for _ in range(N)]
    dp[0][S] = 0

    Q = []
    heapq.heapify(Q)
    heapq.heappush(Q, [0, [0, S]])

    while len(Q) != 0:
        time, [v, s] = heapq.heappop(Q)
        if time > dp[v][s]:
            continue

        if s + C[v] <= MAX:
            ns = s + C[v]
            ntime = time + D[v]
            if dp[v][ns] > ntime:
                dp[v][ns] = ntime
                heapq.heappush(Q, [ntime, [v, ns]])

        for nv, [ns, ntime] in G[v]:
            if s < ns:
                continue
            ns = s - ns
            ntime += time
            if dp[nv][ns] > ntime:
                dp[nv][ns] = ntime
                heapq.heappush(Q, [ntime, [nv, ns]])

    ans = [min(dp[i]) for i in range(1, N)]
    return "\n".join(map(str, ans))


def main():

    sys.setrecursionlimit(10 ** 6)

    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    N = int(next(tokens))  # type: int
    M = int(next(tokens))  # type: int
    S = int(next(tokens))  # type: int
    U = [int()] * (M)  # type: "List[int]"
    V = [int()] * (M)  # type: "List[int]"
    A = [int()] * (M)  # type: "List[int]"
    B = [int()] * (M)  # type: "List[int]"
    for i in range(M):
        U[i] = int(next(tokens))
        V[i] = int(next(tokens))
        A[i] = int(next(tokens))
        B[i] = int(next(tokens))
    C = [int()] * (N)  # type: "List[int]"
    D = [int()] * (N)  # type: "List[int]"
    for i in range(N):
        C[i] = int(next(tokens))
        D[i] = int(next(tokens))
    print(solve(N, M, S, U, V, A, B, C, D))


if __name__ == '__main__':
    main()
